function extractDomain(rawUrl) {
  if (!rawUrl || typeof rawUrl !== 'string') {
    return null;
  }

  let url = rawUrl.trim();

  // Garante protocolo para o parser
  if (!/^https?:\/\//i.test(url)) {
    url = 'https://' + url;
  }

  try {
    const parsedUrl = new URL(url);
    return parsedUrl.hostname.replace(/^www\./i, '');
  } catch (error) {
    // Fallback ultra defensivo
    return rawUrl
      .replace(/^https?:\/\//i, '')
      .replace(/^www\./i, '')
      .split('/')[0]
      .trim();
  }
}

// Prioridade: results → failed_results
const urlFromResults =
  $json.results?.[0]?.url ||
  $json.failed_results?.[0]?.url ||
  null;

return [
  {
    original_url: urlFromResults,
    domain: extractDomain(urlFromResults)
  }
];
